// Generic async retry helper.
//
// Options:
//   retries      number of retries AFTER the first attempt (default 3)
//   baseDelayMs  delay before the first retry (default 100)
//   factor       exponential backoff multiplier (default 2)
//   sleep        (ms, signal) => Promise, injectable for tests
//   signal       optional AbortSignal; aborting cancels further attempts
//
// fn receives the zero-based attempt index.

export function defaultSleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason);
      return;
    }
    const onAbort = () => {
      clearTimeout(t);
      reject(signal.reason);
    };
    const t = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

function throwIfAborted(signal) {
  if (signal?.aborted) throw signal.reason;
}

// Races a promise against the signal so that an abort rejects immediately,
// even if the underlying promise never settles.
function abortable(promise, signal) {
  if (!signal) return promise;
  return new Promise((resolve, reject) => {
    const onAbort = () => reject(signal.reason);
    if (signal.aborted) {
      onAbort();
      return;
    }
    signal.addEventListener('abort', onAbort, { once: true });
    promise.then(
      (v) => {
        signal.removeEventListener('abort', onAbort);
        resolve(v);
      },
      (e) => {
        signal.removeEventListener('abort', onAbort);
        reject(e);
      },
    );
  });
}

export async function retry(fn, opts = {}) {
  const {
    retries = 3,
    baseDelayMs = 100,
    factor = 2,
    sleep = defaultSleep,
    signal,
  } = opts;

  throwIfAborted(signal);

  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    throwIfAborted(signal);
    try {
      return await fn(attempt);
    } catch (err) {
      throwIfAborted(signal);
      if (err?.retryable === false) throw err;
      lastErr = err;
    }

    // No sleep after the final failed attempt.
    if (attempt === retries) break;

    const delay = baseDelayMs * factor ** attempt;
    await abortable(Promise.resolve().then(() => sleep(delay, signal)), signal);
    throwIfAborted(signal);
  }

  throw lastErr;
}

