import { defaults, deepMerge, isKnownLeaf, getPath, setPath, coerce } from './schema.mjs';
import { parseEnv } from './env.mjs';
import { parseArgs } from './cli.mjs';

const hasOwn = (o, k) => Object.prototype.hasOwnProperty.call(o, k);

/** True only for own, non-object leaves of the defaults schema (rejects prototype keys). */
function isOwnLeaf(path) {
  let cur = defaults;
  for (const part of path.split('.')) {
    if (cur === null || typeof cur !== 'object' || !hasOwn(cur, part)) return false;
    cur = cur[part];
  }
  return cur === null || typeof cur !== 'object';
}

/** Deep-copy plain objects so the result never aliases the frozen defaults. */
function clone(obj) {
  return Object.fromEntries(
    Object.entries(obj).map(([k, v]) => [
      k,
      v && typeof v === 'object' && !Array.isArray(v) ? clone(v) : v,
    ]),
  );
}

/** Keep only keys from the config file that exist in the schema. */
function pickKnown(file, prefix = '') {
  const out = {};
  for (const [k, v] of Object.entries(file ?? {})) {
    const path = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      const def = getPath(defaults, path);
      if (def && typeof def === 'object') {
        const sub = pickKnown(v, path);
        if (Object.keys(sub).length) setPath(out, path.split('.').at(-1), sub);
      }
    } else if (isKnownLeaf(path)) {
      out[k] = v;
    }
  }
  return out;
}

/** Turn parsed CLI flags (flat, e.g. 'db.host') into a nested, type-coerced partial config. */
function parseCli(argv) {
  const out = {};
  for (const [path, raw] of Object.entries(parseArgs(argv))) {
    if (!isOwnLeaf(path)) continue;
    const value = coerce(path, raw);
    if (value !== undefined) setPath(out, path, value);
  }
  return out;
}

/**
 * Resolve configuration. Precedence: defaults < file < env < CLI flags.
 * @param {{ file?: object, env?: Record<string,string>, argv?: string[] }} sources
 */
export function loadConfig({ file = {}, env = {}, argv = [] } = {}) {
  let cfg = clone(defaults);
  cfg = deepMerge(cfg, pickKnown(file));
  cfg = deepMerge(cfg, parseEnv(env));
  cfg = deepMerge(cfg, parseCli(argv));
  return cfg;
}

